mapper.update:
UPDATE SYM0YA
   SET JM_NM          = #{jmNm, jdbcType=VARCHAR}
     , BALH_NATION    = #{balhNation, jdbcType=VARCHAR}
     , CURRENCY       = #{currency, jdbcType=VARCHAR}
     , AEKM           = #{aekm, jdbcType=NUMERIC}
     , SANGJ_YMD      = CASE WHEN #{sangjYmd, jdbcType=VARCHAR} IS NOT NULL AND TRIM(#{sangjYmd, jdbcType=VARCHAR}) != ''
                             THEN TO_DATE(SUBSTR(REGEXP_REPLACE(#{sangjYmd, jdbcType=VARCHAR}, '[^0-9]', ''), 1, 8), 'YYYYMMDD')
                             ELSE NULL END
     , SANGJ_JUSU     = #{sangjJusu, jdbcType=NUMERIC}
     , BLBG_TCKR      = #{blbgTckr, jdbcType=VARCHAR}
     , BLBG_TCKR_TEXT = #{blbgTckrText, jdbcType=VARCHAR}
     , ISIN_CD        = #{isinCd, jdbcType=VARCHAR}
     , SIGA_AGENT     = #{sigaAgent, jdbcType=VARCHAR}
     , JASAN_ATTR     = #{jasanAttr, jdbcType=VARCHAR}
     , SJ_GB          = #{sjGb, jdbcType=VARCHAR}
     , SEDOL          = #{sedol, jdbcType=VARCHAR}
     , FEN0055        = #{fen0055, jdbcType=VARCHAR}
     , BALH_NM        = #{balhNm, jdbcType=VARCHAR}
     , JASAN          = #{jasan, jdbcType=VARCHAR}
     , GBX            = COALESCE(#{gbx, jdbcType=VARCHAR}, 'N')
     , STOCK_GB       = #{stockGb, jdbcType=VARCHAR}
     , SRS_CD         = #{srsCd, jdbcType=VARCHAR}
 WHERE CORP_GR  = #{corpGr}
   AND JM_CD    = #{jmCd}
   AND JASAN_GB = COALESCE(#{jasanGb, jdbcType=VARCHAR}, '1')

